import { Router } from "express";
import rateLimit from "express-rate-limit";

import {
  getPresignedR2Url,
  getR2ObjectMetadata,
} from "@/infrastructure/storage/r2.client.js";
import { AppError } from "@/shared/http/AppError.js";

// These are the immutable keys generated by the three public image uploaders.
// Never allow an entire tenant prefix: it also contains private communications
// and custom-order attachments. New upload formats require an explicit review.
const tenant = "[a-f0-9]{24}";
const uuid =
  "[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}";
const timestampedImage = `[0-9]{13}-${uuid}\\.(?:jpg|png|webp)`;
const publicImageKey = new RegExp(
  `^(?:public-sites/${tenant}/(?:logo|favicon|cover|homeHero|loginBackground|registerBackground|courseHero)/${timestampedImage}|tenants/${tenant}/products/${timestampedImage}|tenants/${tenant}/voucher-assets/${uuid}\\.(?:jpg|png))$`,
);
const imageContentTypes = {
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
} as const;
const maximumImageBytes = 8 * 1024 * 1024;

export const publicMediaRouter = Router();
export const publicMediaLimiter = rateLimit({
  windowMs: 60_000,
  limit: 600,
  standardHeaders: "draft-7",
  legacyHeaders: false,
  message: {
    code: "PUBLIC_MEDIA_RATE_LIMITED",
    message: "Too many image requests.",
  },
});

publicMediaRouter.use((_req, res, next) => {
  res.set({
    "Cache-Control": "no-store",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
  });
  next();
}, publicMediaLimiter);

publicMediaRouter.use(async (req, res, next) => {
  if (req.method !== "GET" && req.method !== "HEAD") {
    res.set("Allow", "GET, HEAD").status(405).end();
    return;
  }

  // Inspect the raw URL before decoding or normalizing it. All generated keys
  // are plain ASCII; percent-encoded aliases, traversal and separators are not
  // needed. Express wildcard parameters would already have decoded them.
  const path = req.url.split("?", 1)[0];
  const key = path.startsWith("/") ? path.slice(1) : "";
  if (!publicImageKey.test(key)) {
    res.status(404).end();
    return;
  }

  const extension = key.slice(
    key.lastIndexOf(".") + 1,
  ) as keyof typeof imageContentTypes;
  const contentType = imageContentTypes[extension];
  try {
    const object = await getR2ObjectMetadata({ key });
    if (
      object.contentType !== contentType ||
      !Number.isSafeInteger(object.contentLength) ||
      object.contentLength <= 0 ||
      object.contentLength > maximumImageBytes
    ) {
      res.status(404).end();
      return;
    }

    // HEAD must not redirect to a GET signature: S3 signs the HTTP method.
    if (req.method === "HEAD") {
      res
        .set({
          "Content-Type": contentType,
          "Content-Length": String(object.contentLength),
          "Content-Disposition": "inline",
        })
        .status(200)
        .end();
      return;
    }

    const location = await getPresignedR2Url({
      key,
      expiresInSeconds: 300,
      responseContentType: contentType,
      responseContentDisposition: "inline",
      responseCacheControl: "no-store",
    });
    // The browser downloads directly from private R2. Neither this redirect nor
    // its target is cached beyond its signature, and the API buffers no image.
    res.set("Location", location).status(302).end();
  } catch (error) {
    const storageError = error as {
      name?: string;
      $metadata?: { httpStatusCode?: number };
    };
    if (
      storageError?.name === "NotFound" ||
      storageError?.name === "NoSuchKey" ||
      storageError?.$metadata?.httpStatusCode === 404
    ) {
      res.status(404).end();
      return;
    }
    // Do not expose provider messages, bucket names or signed URLs on errors.
    next(
      new AppError({
        statusCode: 503,
        code: "PUBLIC_MEDIA_UNAVAILABLE",
        message: "Public image storage is temporarily unavailable.",
      }),
    );
  }
});

export default publicMediaRouter;
